function spouseFieldValues(source,field){
 const keys=/^(?:conjuge|cônjuge)$/.test(field)?['conjuge','cônjuge']:[field];
 return source.split('\n').flatMap(line=>{const match=line.match(/^\|\s*([^=]+?)\s*=([^\n]*)$/);return match&&keys.includes(match[1].trim())?[match[2].trim()]:[];});
}
